sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var body = request.body.data;

if (body.action == "create") {

    var asset = new GlideRecord('alm_asset');
    asset.initialize();

    asset.display_name = body.display_name;
    asset.asset_tag = body.asset_tag;
    asset.serial_number = body.serial_number;
    asset.setValue('model_category' , body.model_category);
	asset.setValue('model', body.model);
    asset.install_status = body.install_status;
    asset.substatus = body.substatus;
    asset.assigned_to = body.assigned_to;
    asset.company = body.company;
    asset.location = body.location;
    asset.cost = body.cost;
    asset.purchase_date = body.purchase_date;

    var sysId = asset.insert();

}


    response.setStatus(201);
    response.setBody({
        status: "success",
        message: "Asset created successfully",
        sys_id: sysId,

    });

})(request, response);
